    assert_eq!(r["ok"], false, "{r}");
    assert!(r["error"].as_str().unwrap().contains("An export is about to add its files to Apple Photos (import 1)"), "{r}");
    go.send(()).unwrap();
    let t0 = Instant::now();
    while h.app.export.is_some() {
